<?php
namespace App\Services\Face;
use App\Contracts\{FaceProvider,ProtectedMediaStorage};use App\Models\{FaceCollection,FaceMatchResult,FaceSearchSubject,IndexedFace,MediaAsset};use Illuminate\Support\Facades\DB;use RuntimeException;
class FaceRecognitionManager{public function __construct(private FaceProvider$provider,private ProtectedMediaStorage$storage){}public function collection(int$groupId):FaceCollection{$key=preg_replace('/[^a-zA-Z0-9_.-]/','-',config('face.collection_prefix').'-event-'.$groupId);return FaceCollection::firstOrCreate(['group_id'=>$groupId],['provider'=>config('face.provider'),'provider_collection_ref'=>$this->provider->resolveCollection($key),'state'=>'active']);}public function index(MediaAsset$asset):void{$collection=$this->collection($asset->group_id);if(IndexedFace::where('face_collection_id',$collection->id)->where('media_asset_id',$asset->id)->where('state','ready')->exists())return;$variant=$asset->variant('optimized')??$asset->variant('original');if(!$variant||!$this->storage->exists($variant->object_key))throw new RuntimeException('Index source unavailable.');$stream=$this->storage->readStream($variant->object_key);$bytes=stream_get_contents($stream);fclose($stream);$result=$this->provider->indexFace($collection->provider_collection_ref,$asset->uuid,$bytes);IndexedFace::updateOrCreate(['face_collection_id'=>$collection->id,'provider_face_ref'=>$result['face_id']],['media_asset_id'=>$asset->id,'provider_external_ref'=>$asset->uuid,'confidence'=>$result['confidence']??null,'state'=>'ready']);}public function search(FaceSearchSubject$subject):void{$consent=$subject->consent;if($consent->state!=='granted'||$consent->withdrawn_at)throw new RuntimeException('Biometric consent is not active.');if($subject->expires_at->isPast())throw new RuntimeException('Selfie has expired.');$collection=$this->collection($subject->group_id);$stream=$this->storage->readStream($subject->object_key);$bytes=stream_get_contents($stream);fclose($stream);$matches=$this->provider->search($collection->provider_collection_ref,$bytes,(float)config('face.threshold',95),(int)config('face.max_results',100));DB::transaction(function()use($subject,$matches){$subject->results()->delete();foreach($matches as$m){$asset=MediaAsset::where('uuid',$m['external_id']??'')->where('group_id',$subject->group_id)->first();if(!$asset)continue;FaceMatchResult::create(['face_search_subject_id'=>$subject->id,'media_asset_id'=>$asset->id,'similarity'=>(float)$m['similarity'],'review_state'=>config('face.manual_review')?'unreviewed':'accepted','expires_at'=>config('face.result_retention_days')?now()->addDays((int)config('face.result_retention_days')):null]);}$subject->update(['state'=>'completed','error'=>null]);});}public function purgeSubject(FaceSearchSubject$s):void{if($this->storage->exists($s->object_key))$this->storage->delete($s->object_key);$s->delete();}public function health():array{return$this->provider->health();}}
